class TreeAncestor:
    def __init__(self, n, parent):
        LOG = 16  # up to 2^16 > 10^5
        self.up = [[-1]*LOG for _ in range(n)]
        for i in range(n):
            self.up[i][0] = parent[i]
        for j in range(1, LOG):
            for i in range(n):
                if self.up[i][j-1] != -1:
                    self.up[i][j] = self.up[self.up[i][j-1]][j-1]
    def getKthAncestor(self, node, k):
        for j in range(16):
            if k & (1 << j):
                node = self.up[node][j]
                if node == -1:
                    break
        return node
